      "criterion_id": "GC3",
      "description": "report.json.project equals the value of input.txt.project",
      "required": true
    },
    {
      "criterion_id": "GC4",
      "description": "report.json.doubled_count equals input.txt.count multiplied by two",
      "required": true
    }
